import{_ as a,o,c as r,ae as t}from"./chunks/framework.CLL1HkDi.js";const u=JSON.parse('{"title":"World Generation and Smart Prefabs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/world-gen.md","filePath":"guide/world-gen.md"}'),i={name:"guide/world-gen.md"};function l(n,e,s,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="world-generation-and-smart-prefabs" tabindex="-1">World Generation and Smart Prefabs <a class="header-anchor" href="#world-generation-and-smart-prefabs" aria-label="Permalink to &quot;World Generation and Smart Prefabs&quot;">​</a></h1><h2 id="world-generation" tabindex="-1">World Generation <a class="header-anchor" href="#world-generation" aria-label="Permalink to &quot;World Generation&quot;">​</a></h2><p>The plugin uses a custom implementation of <code>IWorldGenProvider</code> to generate a repeatable grid of plots.</p><h3 id="grid-logic" tabindex="-1">Grid Logic <a class="header-anchor" href="#grid-logic" aria-label="Permalink to &quot;Grid Logic&quot;">​</a></h3><p>The world is divided into regions of <code>(PlotSize + RoadSize)</code>.</p><ul><li><strong>Plots</strong> are generated at the start of each grid cell.</li><li><strong>Roads</strong> fill the remaining space along the X and Z axes.</li><li><strong>Intersections</strong> are placed at the crossing of two roads.</li></ul><h3 id="terrain-layers" tabindex="-1">Terrain Layers <a class="header-anchor" href="#terrain-layers" aria-label="Permalink to &quot;Terrain Layers&quot;">​</a></h3><ul><li><strong>Bedrock (Y=0):</strong> Prevents falling into the void.</li><li><strong>Sub-surface (Y=1 to 63):</strong> Filled with the configured <code>Filling</code> material.</li><li><strong>Surface (Y=64):</strong> Uses <code>PlotSurface</code> for plots and <code>RoadSurface</code> for roads.</li></ul><hr><h2 id="world-spawning-logic" tabindex="-1">World Spawning Logic <a class="header-anchor" href="#world-spawning-logic" aria-label="Permalink to &quot;World Spawning Logic&quot;">​</a></h2><p>The generator uses a prioritized search for the initial world spawn point:</p><ol><li><strong>Custom Spawn:</strong> If <code>CustomSpawn</code> is set in <code>config.json</code>, it is always used.</li><li><strong>Safe Floor Search:</strong> If a plot prefab is loaded, the generator searches its center area (6x6 blocks) for the highest solid floor (filtering out foliage like leaves, logs, or flowers).</li><li><strong>Roadless / Island Situations:</strong> If no safe floor is found in the prefab, or if roads/intersections are disabled (<code>RoadSize: 0</code>), the generator defaults to the corner of the plot grid coordinate.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For roadless &quot;infinite sea&quot; worlds or island prefabs, we highly recommend using <code>/plot setspawn</code> to define a pleasant starting point for your players, as the default math may place them at a junction corner.</p></div><hr><h2 id="smart-prefabs" tabindex="-1">Smart Prefabs <a class="header-anchor" href="#smart-prefabs" aria-label="Permalink to &quot;Smart Prefabs&quot;">​</a></h2><p>The smart prefab system automatically handles how your schematic looks in the world.</p><h3 id="automatic-centralization" tabindex="-1">Automatic Centralization <a class="header-anchor" href="#automatic-centralization" aria-label="Permalink to &quot;Automatic Centralization&quot;">​</a></h3><p>If your plot prefab is smaller than the grid size (e.g., a 20x20 island in a 32x32 plot), the plugin will calculate the offsets automatically to place it in the center.</p><h3 id="skip-air-logic" tabindex="-1">Skip-Air Logic <a class="header-anchor" href="#skip-air-logic" aria-label="Permalink to &quot;Skip-Air Logic&quot;">​</a></h3><p>When a prefab contains blocks named &quot;Empty&quot; or &quot;Air&quot;, the plugin skips them. This allows the underlying terrain (like plot water) to show through, creating perfect islands.</p><h3 id="fluid-support" tabindex="-1">Fluid Support <a class="header-anchor" href="#fluid-support" aria-label="Permalink to &quot;Fluid Support&quot;">​</a></h3><p>If you place fluids in your prefab, the plugin will correctly register them as Hytale fluids, enabling rendering and physics.</p>',22)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
